{"path": "/workspace/lib/books.ts", "content": "import { promises as fs } from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";

export type BookStatus = "reading" | "finished";

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  addedAt: string;
  finishedAt: string | null;
}

export interface NewBookInput {
  title: string;
  author: string;
  notes?: string;
}

export const LIMITS = { title: 200, author: 200, notes: 10_000 } as const;

export class ValidationError extends Error {}

// Where the books live. Override with BOOKS_FILE (used by the tests).
function dataFile(): string {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

async function readAll(): Promise<Book[]> {
  let raw: string;
  try {
    raw = await fs.readFile(dataFile(), "utf8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
  // A broken file is an error, not an empty list, so we never overwrite
  // someone's books with [] after a bad hand edit.
  const parsed: unknown = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error(`${dataFile()} should contain a JSON array of books`);
  }
  return parsed as Book[];
}

// Write to a temp file and rename it into place, so a crash mid-write
// can't leave a half-written books.json behind.
async function writeAll(books: Book[]): Promise<void> {
  const file = dataFile();
  await fs.mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${randomBytes(4).toString("hex")}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await fs.rename(tmp, file);
}

// Run read-modify-write updates one at a time so two quick submissions
// can't overwrite each other. Kept on globalThis so it survives dev reloads.
const g = globalThis as { __booksQueue?: Promise<unknown> };
function serialize<T>(fn: () => Promise<T>): Promise<T> {
  const run = (g.__booksQueue ?? Promise.resolve()).then(fn, fn);
  g.__booksQueue = run.catch(() => {});
  return run;
}

function newId(existing: Book[]): string {
  let id: string;
  do {
    id = randomBytes(6).toString("base64url");
  } while (existing.some((b) => b.id === id));
  return id;
}

function clean(value: unknown, field: keyof typeof LIMITS, required: boolean): string {
  const text = typeof value === "string" ? value.trim() : "";
  if (required && !text) throw new ValidationError(`Please enter the ${field}.`);
  if (text.length > LIMITS[field]) {
    throw new ValidationError(`The ${field} is too long (max ${LIMITS[field]} characters).`);
  }
  return text;
}

export async function listBooks(): Promise<{ reading: Book[]; finished: Book[] }> {
  const books = await readAll();
  const reading = books
    .filter((b) => b.status === "reading")
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));
  return { reading, finished };
}

export async function getBook(id: string): Promise<Book | null> {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export function addBook(input: NewBookInput): Promise<Book> {
  const title = clean(input.title, "title", true);
  const author = clean(input.author, "author", true);
  const notes = clean(input.notes, "notes", false);

  return serialize(async () => {
    const books = await readAll();
    const book: Book = {
      id: newId(books),
      title,
      author,
      notes,
      status: "reading",
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    await writeAll([...books, book]);
    return book;
  });
}

/** Marks a book as finished. Returns null if no book has that id. */
export function markFinished(id: string): Promise<Book | null> {
  return serialize(async () => {
    const books = await readAll();
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    if (book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await writeAll(books);
    }
    return book;
  });
}
"}

