import { revalidatePath } from "next/cache";
import { addBook, markFinished, ValidationError } from "@/lib/books";

export interface AddBookState {
  ok: boolean;
  error?: string;
  // Sent back on error so the form keeps what was typed.
  values?: { title: string; author: string; notes: string };
}

export async function addBookAction(
  _prev: AddBookState,
  formData: FormData,
): Promise<AddBookState> {
  const values = {
    title: String(formData.get("title") ?? ""),
    author: String(formData.get("author") ?? ""),
    notes: String(formData.get("notes") ?? ""),
  };
  try {
    await addBook(values);
  } catch (err) {
    if (err instanceof ValidationError) return { ok: false, error: err.message, values };
    throw err;
  }
  revalidatePath("/");
  return { ok: true };
}

export async function markFinishedAction(id: string): Promise<void> {
  await markFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}
"}

