{"path": "/workspace/app/page.tsx", "content": "import Link from "next/link";
import { connection } from "next/server";
import { listBooks, type Book } from "@/lib/books";
import { AddBookForm } from "./add-book-form";
import { FinishButton } from "./finish-button";
import { formatDate } from "./format";

export default async function Home() {
  await connection(); // read the JSON file on every request, not at build time
  const { reading, finished } = await listBooks();

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="muted">Nothing on the go. Add a book below.</p>
        ) : (
          <ul className="books">
            {reading.map((book) => (
              <li key={book.id}>
                <BookSummary book={book} />
                <FinishButton id={book.id} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="muted">No finished books yet.</p>
        ) : (
          <ul className="books">
            {finished.map((book) => (
              <li key={book.id}>
                <BookSummary book={book} />
                {book.finishedAt && (
                  <span className="muted small">Finished {formatDate(book.finishedAt)}</span>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>

      <AddBookForm />
    </>
  );
}

function BookSummary({ book }: { book: Book }) {
  return (
    <div>
      <Link href={`/books/${book.id}`} className="title">
        {book.title}
      </Link>
      <div className="muted">{book.author}</div>
    </div>
  );
}
"}

