{"path": "/workspace/app/books/[id]/page.tsx", "content": "import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { getBook } from "@/lib/books";
import { FinishButton } from "../../finish-button";
import { formatDate } from "../../format";
import { CopyLinkButton } from "./copy-link-button";

export async function generateMetadata(props: PageProps<"/books/[id]">): Promise<Metadata> {
  const { id } = await props.params;
  const book = await getBook(id);
  if (!book) return { title: "Book not found" };
  return {
    title: `${book.title} by ${book.author}`,
    description: book.notes ? book.notes.slice(0, 160) : `${book.title} by ${book.author}`,
  };
}

export default async function BookPage(props: PageProps<"/books/[id]">) {
  await connection();
  const { id } = await props.params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <article className="card">
      <p>
        <Link href="/">← All books</Link>
      </p>
      <h2 className="book-title">{book.title}</h2>
      <p className="author">by {book.author}</p>
      <p className="muted small">
        {book.status === "finished" && book.finishedAt
          ? `Finished ${formatDate(book.finishedAt)}`
          : `Reading since ${formatDate(book.addedAt)}`}
      </p>

      <h3>Notes</h3>
      {book.notes ? <p className="notes">{book.notes}</p> : <p className="muted">No notes.</p>}

      <div className="actions">
        {book.status === "reading" && <FinishButton id={book.id} />}
        <CopyLinkButton />
      </div>
    </article>
  );
}
"}

